                                    let all_scratch = res.written && range <= SCRATCH_BYTES && super::tune::scratch_all();
                                    let want = !all_scratch && allow_shadow && shadow_writes() && res.written && range <= super::tune::shadow_max() && (res.atomic || range >= shadow_min());
