                                        (r.bias, r.size) = (lo, hi - lo);
                                        let r = *r;
                                        bound.shadows.push(Shadow { reused: true, ..r });
                                        placement = Placement::ShadowReused;
                                        info = vk::DescriptorBufferInfo { buffer: self.shadow(), offset: r.shadow_off, range };
